        {
          "stage": "specification",
          "sentences": [
            {
              "display_text": "颜色有黑色和米色两种。",
              "spoken_text": "颜色有黑色和米色两种。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
